    public void setComment_setsCommentLinesForPath() {
        when(settingsHolderMock.getComments()).thenReturn(new HashMap<>());
        String path = "path";
        List<String> commentLines = new ArrayList<>();
        commentsConfiguration.setComment(path, commentLines.toArray(new String[0]));
        assertEquals(commentLines, commentsConfiguration.getAllComments().get(path));
    }

    @Test
    public void setComment_setsEmptyLineWithoutMarkerForNewEntry() {
        when(settingsHolderMock.getComments()).thenReturn(new HashMap<>());
        String path = "path";
        List<String> commentLines = new ArrayList<>();
        commentLines.add("");
        commentsConfiguration.setComment(path, commentLines.toArray(new String[0]));
        assertEquals(Collections.singletonList(""), commentsConfiguration.getAllComments().get(path));
    }

    @Test
    public void setComment_overridesExistingEntry() {
        when(settingsHolderMock.getComments()).thenReturn(Map.of("path1", List.of("line1")));
        String path = "path1";
        List<String> commentLines = new ArrayList<>();
        commentLines.add("newLine");
        commentsConfiguration.setComment(path, commentLines.toArray(new String[0]));
        assertEquals(Arrays.asList("newLine"), commentsConfiguration.getAllComments().get(path));
    }

    @Test
    public void getAllComments_returnsEmptyMap() {
        assertNotNull(commentsConfiguration.getAllComments());
        assertTrue(commentsConfiguration.getAllComments().isEmpty());
    }

